package decode

import (
	"strings"
	"testing"
)

// refAPRS is a real Bell-202 AFSK1200 AX.25 capture generated with
// direwolf's gen_packets and committed under tests/data. The pure-Go
// demodulator must recover both frames without multimon-ng.
const refAPRS = "../../../tests/data/ref_aprs.wav"

// refPOCSAG is a synthetic POCSAG page (1200 baud, address 1234567,
// alphanumeric "HELLO PAGER TEST 123") generated by tools/gen_test_wavs.py
// using multimon-ng's BCH(31,21) encoder.
const refPOCSAG = "../../../tests/data/ref_pocsag.wav"

func TestAFSKReference(t *testing.T) {
	packets, err := AFSKFrames(refAPRS)
	if err != nil {
		t.Fatalf("AFSKFrames: %v", err)
	}
	if len(packets) != 2 {
		t.Fatalf("got %d packets, want 2: %+v", len(packets), packets)
	}
	first := packets[0]
	if first.Source != "M0XXX-9" {
		t.Errorf("source = %q, want M0XXX-9", first.Source)
	}
	if first.Destination != "APZSAT-0" {
		t.Errorf("destination = %q, want APZSAT-0", first.Destination)
	}
	if !strings.Contains(first.Info, "Hello from space!") {
		t.Errorf("info = %q, want it to contain %q", first.Info, "Hello from space!")
	}
}

func TestFindBurstsNoPanic(t *testing.T) {
	// An even number of subsampled power values used to index past the
	// end of the slice while taking the median.
	samples, rate, err := ReadWAV(refAPRS)
	if err != nil {
		t.Fatalf("ReadWAV: %v", err)
	}
	if bursts := findBursts(samples, rate, rate/2); len(bursts) == 0 {
		t.Log("no bursts found (tolerated; gating is optional)")
	}
}

// The remaining fixtures are generated by tools/gen_test_wavs.py and
// committed under tests/data so the decoders are exercised against real
// PCM, not mocks.

const (
	refDTMF  = "../../../tests/data/ref_dtmf.wav"
	refRTTY  = "../../../tests/data/ref_rtty.wav"
	refSSTV  = "../../../tests/data/ref_sstv.wav"
	refPSK31 = "../../../tests/data/ref_psk31.wav"
	refMorse = "../../../tests/data/ref_morse.wav"
)

func TestMorseReference(t *testing.T) {
	result, err := MorseDecode(refMorse)
	if err != nil {
		t.Fatalf("MorseDecode: %v", err)
	}
	if !strings.Contains(result.Text, "CQ DE RS44 SAT") {
		t.Errorf("text = %q, want it to contain the sent text", result.Text)
	}
	if result.ToneHz < 650 || result.ToneHz > 750 {
		t.Errorf("tone = %.1f Hz, want about 700 Hz", result.ToneHz)
	}
	// The fixture keys at 60 ms per dot; anything far from that is a
	// mis-measured element length rather than a real signal.
	if result.DotMs < 45 || result.DotMs > 80 {
		t.Errorf("dot = %.1f ms, want about 60 ms", result.DotMs)
	}
}

// TestMorseRejectsNoise checks that a loud noise burst is not reported as
// CW text: real noise keys into plausible run lengths, so the decoder has
// to judge the timing before it trusts the characters.
func TestMorseRejectsNoise(t *testing.T) {
	rate := 8000
	samples := make([]float64, rate*10)
	seed := uint32(12345)
	for i := range samples {
		seed = seed*1664525 + 1013904223
		samples[i] = float64(int32(seed)) / float64(1<<31) * 0.5
	}
	result, tone, snr := morseFromSamples(samples, rate)
	if result.Text != "" {
		t.Errorf("noise decoded as %q, want no text", result.Text)
	}
	if tone <= 0 {
		t.Error("no tone reported for the noise")
	}
	_ = snr
}

func TestDTMFReference(t *testing.T) {
	samples, rate, err := ReadWAV(refDTMF)
	if err != nil {
		t.Fatalf("ReadWAV: %v", err)
	}
	got := DTMFDecode(samples, rate)
	want := "0123456789*#ABCD"
	if got != want {
		t.Errorf("DTMFDecode = %q, want %q", got, want)
	}
}

func TestRTTYReference(t *testing.T) {
	samples, rate, err := ReadWAV(refRTTY)
	if err != nil {
		t.Fatalf("ReadWAV: %v", err)
	}
	got := RTTYDecode(samples, rate, 2125, 1955, 45.45)
	if !strings.Contains(got, "CQ DE RS44 RTTY TEST 599") {
		t.Errorf("RTTYDecode = %q, want it to contain the sent text", got)
	}
}

func TestSSTVReference(t *testing.T) {
	samples, rate, err := ReadWAV(refSSTV)
	if err != nil {
		t.Fatalf("ReadWAV: %v", err)
	}
	got := SSTVDetect(samples, rate)
	if len(got) == 0 {
		t.Fatal("SSTVDetect found no VIS header")
	}
	if got[0].VIS != 0x3C {
		t.Errorf("VIS = 0x%02X, want 0x3C (Martin M2)", got[0].VIS)
	}
	if got[0].Mode != "Martin M2" {
		t.Errorf("mode = %q, want Martin M2", got[0].Mode)
	}
}

func TestPSK31Reference(t *testing.T) {
	samples, rate, err := ReadWAV(refPSK31)
	if err != nil {
		t.Fatalf("ReadWAV: %v", err)
	}
	got := PSK31Decode(samples, rate, 1000)
	if !strings.Contains(got, "CQ DE RS44 PSK31 TEST") {
		t.Errorf("PSK31Decode = %q, want it to contain the sent text", got)
	}
}

func TestPOCSAGReference(t *testing.T) {
	samples, rate, err := ReadWAV(refPOCSAG)
	if err != nil {
		t.Fatalf("ReadWAV: %v", err)
	}
	msgs := POCSAGDecode(samples, rate, 1200)
	if len(msgs) != 1 {
		t.Fatalf("got %d pages, want 1: %+v", len(msgs), msgs)
	}
	if msgs[0].Address != 1234567 {
		t.Errorf("address = %d, want 1234567", msgs[0].Address)
	}
	if msgs[0].Function != 3 {
		t.Errorf("function = %d, want 3", msgs[0].Function)
	}
	if msgs[0].Alpha != "HELLO PAGER TEST 123" {
		t.Errorf("alpha = %q, want HELLO PAGER TEST 123", msgs[0].Alpha)
	}
}
